INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('ea-animal-welfare-fund','Animal Welfare Fund (EA Funds)','funder',NULL,'funding','aquatic','active','{"aliases":["EA Animal Welfare Fund","AWF","Animal Welfare Fund"],"categories":["funding"],"species":["farmed-fish","crustaceans","chickens","insects","wild-animals","farmed-animals"],"regions":["global","asia","africa","latin-america"],"countries":[],"interventions":["grantmaking"],"approach":"neutral-infrastructure","summary":"Grantmaking fund under EA Funds; its stated goals include aquatic animal welfare R&D and on-farm improvements for farmed shrimp and fish in Asia, Africa and Latin America, and making humane slaughter the default for shrimp.","website":"https://funds.effectivealtruism.org/funds/animal-welfare","hq":"United Kingdom","founded":null,"sources":[{"url":"https://funds.effectivealtruism.org/funds/animal-welfare","title":"Animal Welfare Fund | Effective Altruism Funds","accessed":"2026-11-05","published":null},{"url":"https://funds.effectivealtruism.org/about-us","title":"About us | Effective Altruism Funds","accessed":"2026-11-05","published":null}],"notes":"''hq'' reflects the UK registered office of the EA Funds legal entities shown in the site footer. Grant reports are published on the EA Forum. No RSS feed found. | EA Funds is operated under Centre for Effective Altruism entities (US and UK) per the about page; HQ recorded as UK (Oxford registered office) — uncertain. No feed found.","merged_from":["ea-animal-welfare-fund"]}',0,'2026-11-05','2026-11-13T16:34:54.294Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('coefficient-giving','Coefficient Giving','funder',NULL,'funding','aquatic','active','{"aliases":["Open Philanthropy","Open Philanthropy Project","Open Phil"],"categories":["funding"],"species":["farmed-fish","crustaceans","farmed-animals"],"regions":["global"],"countries":[],"interventions":["grantmaking"],"approach":"neutral-infrastructure","summary":"Philanthropic funder (formerly Open Philanthropy) whose farm animal welfare grantmaking includes aquatic projects, e.g. support for ASC''s Responsible Shrimp Slaughter Project and Friend of the Sea''s Fish Welfare Project.","website":"https://coefficientgiving.org/","hq":"United States","founded":"2011","sources":[{"url":"https://asc-aqua.org/news/shrimp-welfare-project/","title":"ASC launches project to bridge science-to-practice gap in shrimp welfare","accessed":"2026-11-05","published":"2026-09-28"},{"url":"https://friendofthesea.org/marine-conservation-projects-and-awareness/fish-welfare/","title":"Fish Welfare Project — Friend of the Sea","accessed":"2026-11-05","published":null},{"url":"https://friendofthesea.org/fos-and-fair-fish-awarded-open-philantropy-project-grant-to-boost-fish-welfare/","title":"FoS and fair-fish awarded Open Philanthropy Project grant to boost Fish Welfare","accessed":"2026-11-05","published":"2018-01-16"},{"url":"https://www.vox.com/future-perfect/469038/open-philanthropy-coefficient-giving-name-change","title":"One of the world''s most influential philanthropies is changing its name (Vox)","accessed":"2026-11-05","published":"2025-11-18"},{"url":"https://en.wikipedia.org/wiki/Coefficient_Giving","title":"Coefficient Giving - Wikipedia","accessed":"2026-11-05","published":null}],"notes":"coefficientgiving.org returned HTTP 403 to curl and WebFetch, so its own pages were not read. The link to Open Philanthropy is inferred from openphilanthropy.org redirecting to coefficientgiving.org. Grant amounts not verified. | coefficientgiving.org (and openphilanthropy.org redirect) returned 403 to the research fetcher. Formation 2011 and San Francisco location per Wikipedia. Its Farm Animal Welfare fund details not verified directly.","merged_from":["coefficient-giving"]}',0,'2026-11-05','2026-11-13T16:34:54.294Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('essere-animali','Essere Animali','organisation',NULL,'advocacy-campaigns','aquatic','active','{"aliases":[],"categories":["advocacy-campaigns","policy-law"],"species":["farmed-fish","farmed-animals","pigs","chickens"],"regions":["europe"],"countries":["IT"],"interventions":["research","legislation-policy","certification-standards","investigations","diet-change","public-awareness"],"approach":"mixed","summary":"Italian animal protection organisation; aquatic work includes a 2023 report finding that pre-slaughter stunning of farmed fish would have little impact on production costs and criticism of Italy''s ''Sustainable Aquaculture'' certification for lacking a stunning requirement.","website":"https://www.essereanimali.org/","hq":"Italy","founded":null,"sources":[{"url":"https://www.eurogroupforanimals.org/news/new-report-reveals-minimal-cost-fish-welfare","title":"New report reveals the minimal cost of fish welfare — Eurogroup for Animals","accessed":"2026-11-05","published":"2023-02-14"},{"url":"https://www.essereanimali.org/","title":"Essere Animali - Organizzazione per i Diritti Animali","accessed":"2026-11-05","published":null},{"url":"https://www.essereanimali.org/chi-siamo/","title":"Chi siamo - Essere Animali","accessed":"2026-11-05","published":null}],"notes":"essereanimali.org returned HTTP 502 on every attempt, so the organisation''s own site, current activity and feeds could not be verified; status set to ''unclear''. Facts are from a 2023 Eurogroup page. | Founding year not verified.","merged_from":["essere-animali"]}',0,'2026-11-05','2026-11-13T16:34:54.294Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('ali-aquaculture-certification-benchmark','Aquaculture Certification Schemes Benchmark: Aquatic Animal Welfare','resource','aquatic-life-institute','welfare-science','aquatic','active','{"aliases":["ALI Certification Benchmark"],"categories":["welfare-science","movement-infrastructure"],"species":["farmed-fish","crustaceans","cephalopods"],"regions":["global"],"countries":[],"interventions":["certification-standards","research","data-tools"],"approach":"welfare-reform","summary":"Aquatic Life Institute report comparing welfare requirements in major seafood certification schemes (3rd edition, Oct 2024: 8 schemes and 1 ratings agency) on water quality, stocking density, enrichment, feed, stunning and slaughter, and species prohibitions.","website":"https://www.ali.fish/resource-library/aquaculture-certification-schemes-benchmark-2024","hq":null,"founded":null,"sources":[{"url":"https://www.ali.fish/resource-library/aquaculture-certification-schemes-benchmark-2024","title":"2024 Aquaculture Certification Schemes Benchmark: Aquatic Animal Welfare","accessed":"2026-11-05","published":"2024-10-07"}],"notes":"The 2024 edition carries a published correction on GAP''s insect-feed ban. A later edition was not found during this research.","merged_from":[]}',0,'2026-11-05','2026-11-13T16:34:54.294Z');
INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('wfi-trout-air-asphyxia-analysis','Quantifying the welfare impact of air asphyxia in rainbow trout slaughter','resource','welfare-footprint-institute','welfare-science','aquatic','active','{"aliases":["Welfare Footprint fish slaughter pain track"],"categories":["welfare-science"],"species":["farmed-fish"],"regions":["global"],"countries":[],"interventions":["research","humane-slaughter"],"approach":"research","summary":"Peer-reviewed Welfare Footprint analysis (Scientific Reports, 2025) estimating about 10 (1.9-21.7) minutes of moderate to intense pain per rainbow trout killed by air asphyxia, and modelling the cost-effectiveness of electrical and percussive stunning.","website":"https://welfarefootprint.org/publications/trout-air-asphyxia.html","hq":null,"founded":null,"sources":[{"url":"https://welfarefootprint.org/publications/trout-air-asphyxia.html","title":"Air asphyxia in rainbow trout slaughter | WFI","accessed":"2026-11-05","published":null}],"notes":"DOI 10.1038/s41598-025-04272-1. WFI also hosts a ''Fish welfare at slaughter'' species page and a farmed fish appraisal.","merged_from":[]}',0,'2026-11-05','2026-11-13T16:34:54.294Z');
