INSERT INTO entities (id,name,kind,parent_id,primary_category,section,status,profile,stub,last_checked,updated_at) VALUES ('animal-liberation-front','Animal Liberation Front','banner',NULL,'direct-action','movement','unclear','{"aliases":["ALF"],"categories":["direct-action"],"species":["all-animals","animals-in-research","fur-animals"],"regions":["global","uk","north-america"],"countries":[],"interventions":["direct-action"],"approach":"abolitionist","summary":"Leaderless, decentralised name used since the 1970s by unaffiliated individuals and cells claiming illegal direct actions against animal exploitation. US authorities have described it as a domestic terrorism threat (DHS 2005; FBI testimony 2005).","website":"https://en.wikipedia.org/wiki/Animal_Liberation_Front","hq":null,"founded":"1976","sources":[{"url":"https://en.wikipedia.org/wiki/Animal_Liberation_Front","title":"Animal Liberation Front - Wikipedia","accessed":"2026-11-05","published":null}],"notes":"Not a formal organisation; no official website (Wikipedia used as reference link by design). Wikipedia cites CNN (2005) for FBI official describing animal rights/eco-extremism as the number one domestic terrorism threat, and a 2005 DHS planning document listing ALF. Status ''unclear'' because it is a banner rather than an entity with a lifecycle.","merged_from":[]}',0,'2026-11-05','2026-11-13T16:34:54.294Z');
