INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('ace-mg-round-10-awash','grant_awarded','ACE Movement Grant: AWASH (round 10)','ACE Movement Grant of $26,700 to AWASH, which works with tilapia farmers in Ghana; funds an expansion phase after its pilot, focused on reducing mortality and disease on tilapia farms.','2026','2026-04-29','2026-11-05','https://animalcharityevaluators.org/blog/announcing-our-latest-movement-grant-recipients/','Announcing our latest Movement Grant Recipients - Animal Charity Evaluators',26700,'USD','animal-charity-evaluators','awash',NULL,NULL,'confirmed','[]','curated','Round 10 listed under ''February and March, 2026'' on ACE past-recipients page.','2026-11-13T16:34:54.294Z');
