INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('bbsrc-university-of-stirling-electric-aeration-salmon-welfare','grant_awarded','BBSRC: electric-powered aeration for improved fish welfare in salmon aquaculture','UKRI-BBSRC award of £256,879 (BB/Z515255/1), led by the University of Stirling with partners including Bakkafrost, for on-demand electric-powered aeration to improve fish welfare in salmon aquaculture.','2024-07',NULL,'2026-11-05','https://gtr.ukri.org/find-research-and-innovation/project/8d91e5bd-2a56-483e-9f75-6210a34a7ff2','UKRI Gateway to Research: BB/Z515255/1',256879,'GBP','bbsrc','university-of-stirling',NULL,NULL,'confirmed','[]','curated','Read via GtR API. event_date is the fund start date (2024-07-01 UK time; fund end 2026-09-30); GtR does not give an award date. Welfare-science R&D rather than advocacy.','2026-11-13T16:34:54.294Z');
