INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-ea-animal-welfare-fund-rolling','open_call','EA Animal Welfare Fund: rolling grant applications','Rolling: EA Funds says it is ''always open to applications''; grants range $1,000-$500,000 for people, projects, non-profits and institutions. AWF priorities include aquatic animal welfare and humane shrimp slaughter.','2026-11-05',NULL,'2026-11-05','https://funds.effectivealtruism.org/apply-for-funding','Get funding for your high-impact project | Effective Altruism Funds',NULL,NULL,'ea-animal-welfare-fund',NULL,NULL,NULL,'confirmed','[]','curated','Confirmed open on 2026-11-05 (event_date = date verified). Strategy goals from https://funds.effectivealtruism.org/funds/animal-welfare.','2026-11-13T16:34:54.294Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-fish-welfare-initiative-india-2026','open_call','Fish Welfare Initiative: open call for new ideas for farmed fish welfare in India','Open until 18 Nov 2026 (18:00 IST): FWI funds field interventions, technologies or actionable research for Indian aquaculture; standard grants up to INR 10,00,000 (~USD 10k), exceptional up to INR 50,00,000 (~USD 50k).','2026-10-06','2026-10-06','2026-11-05','https://www.fishwelfareinitiative.org/post/rfp-india','Open Call: Funding New Ideas to Improve the Welfare of Farmed Fishes in India',NULL,NULL,'fish-welfare-initiative',NULL,'2026-11-18',NULL,'confirmed','[]','curated','Open to companies, non-profits, individuals/groups. Publication date from FWI blog RSS feed.','2026-11-13T16:34:54.294Z');
