INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-tiny-beam-fund-fellowship-awards-2026','open_call','Tiny Beam Fund: Fellowship Awards (Burning Questions)','Closed for 2026 (applications 24 Mar-22 Apr 2026). Nine-month fellowships for PhD holders (US$60,000) or near-completion PhD students (US$45,000) to research ''Burning Questions'' on industrial animal agriculture in LMICs.','2026-03-24',NULL,'2026-11-05','https://tinybeamfund.org/Fellowship-Awards','Fellowship Awards - Tiny Beam Fund',NULL,NULL,'tiny-beam-fund',NULL,'2026-04-22',NULL,'uncertain','[]','curated','Recurring; not open as of 2026-11-05. Research Planning Grants are invitation-only as of 2026.','2026-11-13T16:34:54.294Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-ambitious-impact-incubation-feb-2027-factory-farming','open_call','Ambitious Impact incubation programme: February 2027 ''Transforming factory farming''','Closed: applications for AIM''s February 2027 ''Transforming factory farming'' cohort have closed. The fully funded two-month programme provides a charity idea, co-founder matching, training and seed-funding access.','2026',NULL,'2026-11-05','https://www.ambitiousimpact.com/start-a-charity','Start a charity — Ambitious Impact',NULL,NULL,'ambitious-impact',NULL,'2026-09-13','closed','uncertain','[]','curated','Next listed cohort (August 2027) is health systems/livelihoods, not animals; applications open January 2027. AIM was formerly Charity Entrepreneurship. | Also reported at https://joinhive.substack.com/p/august-2026','2026-11-13T16:34:54.294Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('call-horizon-europe-cl6-2027-02-farm2fork-06','open_call','Horizon Europe HORIZON-CL6-2027-02-FARM2FORK-06: small-scale aquatic food production','Forthcoming EU call ''Unleashing the potential of sustainable small-scale aquatic food production and recreational fisheries''; planned opening 20 Apr 2027, deadline 23 Sep 2027. Text says aquatic animal welfare should be considered where relevant.','2027-04-20',NULL,'2026-11-05','https://ec.europa.eu/info/funding-tenders/opportunities/data/topicDetails/horizon-cl6-2027-02-farm2fork-06.json','EU Funding & Tenders topic details: HORIZON-CL6-2027-02-FARM2FORK-06',NULL,NULL,'european-commission',NULL,'2027-09-23','forthcoming','uncertain','[]','curated','Status ''forthcoming'' in the EU Funding & Tenders search API. Human-readable page: https://ec.europa.eu/info/funding-tenders/opportunities/portal/screen/opportunities/topic-details/horizon-cl6-2027-02-farm2fork-06 . Welfare is a secondary consideration, not the call''s focus. No open EU call with animal welfare as primary topic was found.','2026-11-13T16:34:54.294Z');
INSERT INTO events (id,type,title,summary,event_date,source_published,last_checked,source_url,source_title,amount,currency,funder_id,recipient_id,deadline,call_state,status,conflicts_with,origin,notes,created_at) VALUES ('hsus-hsi-rename-humane-world-for-animals-2025','announcement','HSUS and HSI rename to Humane World for Animals','The Humane Society of the United States and Humane Society International adopted a single new name, Humane World for Animals.','2025-02',NULL,'2026-11-05','https://en.wikipedia.org/wiki/Humane_World_for_Animals','Humane World for Animals - Wikipedia',NULL,NULL,NULL,NULL,NULL,NULL,'reported','[]','curated','Wikipedia cites a WJLA report dated 2025-02-13; the organisation''s homepage confirms the ''formerly HSUS and HSI'' wording but no date.','2026-11-13T16:34:54.294Z');
